using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
internal sealed partial class ModernWorkspace {
 bool attachmentBusy;string attachmentMessage="";internal bool IsAttachmentBusy{get{return attachmentBusy;}}
 bool DeleteWithUndo(string kind,string id){try{bool saved=DeletionHistory.PersistChange(store.Value,delegate{if(DeletionHistory.Remove(store.Value,kind,id)==null)throw new InvalidOperationException("Cet élément n’est plus disponible.");},owner.Save);if(saved)Refresh();return saved;}catch(Exception ex){MessageBox.Show(ex.Message,"Suppression impossible");return false;}}
 void RestoreDeleted(string id){try{if(DeletionHistory.PersistChange(store.Value,()=>DeletionHistory.Restore(store.Value,id),owner.Save))Refresh();}catch(Exception ex){MessageBox.Show(ex.Message,"Restauration impossible");}}
 void UndoBanner(StackPanel root){if(store.Value.deleted.Count==0)return;var last=store.Value.deleted[0];var row=new DockPanel();var actions=new StackPanel{Orientation=Orientation.Horizontal};actions.Children.Add(Btn("Annuler",delegate{RestoreDeleted(last.id);},false,true));actions.Children.Add(Btn("Historique",delegate{Go("Suppressions récentes");},false,true));DockPanel.SetDock(actions,Dock.Right);row.Children.Add(actions);var text=T("Dernière suppression · "+DeletionHistory.Title(last),12,Ink);text.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(text);var box=Box(row,new Thickness(12));box.Margin=new Thickness(0,0,0,16);root.Children.Add(box);}
 void DeletedPage(StackPanel root){root.Children.Add(T("Les 50 dernières suppressions de tâches et de rendez-vous sont conservées, même après fermeture de l’application. Les notes ont leur propre corbeille dans Mes notes.",12,Muted,new Thickness(0,0,0,18)));if(store.Value.deleted.Count==0)root.Children.Add(T("Aucune suppression à annuler.",13,Muted));foreach(var record in store.Value.deleted){var item=record;var body=new DockPanel();var restore=Btn("Restaurer",delegate{RestoreDeleted(item.id);},true);DockPanel.SetDock(restore,Dock.Right);body.Children.Add(restore);var text=new StackPanel();text.Children.Add(T(DeletionHistory.Title(item),15));DateTime date;string when=DateTime.TryParse(item.deletedAt,out date)?date.ToLocalTime().ToString("dd/MM/yyyy HH:mm"):"Date inconnue";text.Children.Add(T((item.kind=="task"?"Tâche":"Rendez-vous")+" · supprimé le "+when,11,Muted,new Thickness(0,6,0,0)));body.Children.Add(text);var box=Box(body,new Thickness(15));box.Margin=new Thickness(0,0,0,12);root.Children.Add(box);}}
 void EnableProjectDrop(StackPanel root,string project){root.AllowDrop=true;root.Background=System.Windows.Media.Brushes.Transparent;root.PreviewDragOver+=delegate(object sender,DragEventArgs e){e.Effects=!attachmentBusy&&e.Data.GetDataPresent(DataFormats.FileDrop)&&(e.AllowedEffects&DragDropEffects.Copy)!=0?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};root.PreviewDrop+=delegate(object sender,DragEventArgs e){e.Handled=true;if(attachmentBusy||!e.Data.GetDataPresent(DataFormats.FileDrop)){e.Effects=DragDropEffects.None;return;}var paths=e.Data.GetData(DataFormats.FileDrop) as string[];if(paths==null)return;e.Effects=DragDropEffects.Copy;AttachProjectFiles(project,paths);};}
 Border DropZone(){var body=new StackPanel();body.Children.Add(T(attachmentBusy?"Copie des fichiers en cours…":"Déposez vos fichiers ici ou ailleurs sur cette page",13,AccentText));body.Children.Add(T("Copie dans ce projet · 20 fichiers par dépôt · 50 Mo par fichier",11,Muted,new Thickness(0,6,0,0)));if(!String.IsNullOrEmpty(attachmentMessage))body.Children.Add(T(attachmentMessage,11,Muted,new Thickness(0,9,0,0)));var zone=Box(body,new Thickness(15));zone.Background=SelectionBrush;zone.Margin=new Thickness(0,0,0,15);return zone;}
 async void AttachProjectFiles(string project,string[] paths){if(attachmentBusy)return;attachmentBusy=true;attachmentMessage="";Refresh();try{var result=await Task.Run(()=>ProjectFileBatch.Copy(store,paths));var space=ProjectData.Get(store.Value,project);space.files.AddRange(result.Files);if(result.Files.Count>0&&!owner.Save()){foreach(var file in result.Files)space.files.Remove(file);attachmentMessage="La copie a été réalisée, mais l’ajout au projet n’a pas pu être enregistré.";return;}attachmentMessage=result.Files.Count+" fichier(s) ajouté(s)"+(result.Errors.Count>0?" · "+result.Errors.Count+" élément(s) ignoré(s)":"");if(result.Errors.Count>0)MessageBox.Show(attachmentMessage+"\n\n"+String.Join("\n",result.Errors),"Ajout de fichiers");}catch(Exception ex){attachmentMessage="Ajout impossible : "+ex.Message;MessageBox.Show(ex.Message,"Ajout de fichiers");}finally{attachmentBusy=false;Refresh();}}
 internal void PreviewUndoDrop(string path){var old=store.Value.deleted.ToList();var task=new WorkTask{id="preview-deleted",title="Envoyer les plans mis à jour",project="Travail",priority="Normale",status="todo",due=""};store.Value.tasks.Add(task);DeletionHistory.Remove(store.Value,"task",task.id);OpenProject("Travail");Preview(path+"-depot.png");var scroll=content.Content as ScrollViewer;if(scroll!=null){scroll.ScrollToBottom();UpdateLayout();Preview(path+"-zone.png");}selected="Suppressions récentes";Refresh();Preview(path+"-suppressions.png");store.Value.deleted=old;}
}
